(()=>{
 'use strict';
 const D=TarotData,E=TarotEngine,A=TarotArt,$=s=>document.querySelector(s),h=E.escape;
 const app=$('#app'),modal=$('#modal');
 let favorites=E.safeLoad('favorites',[]),history=E.safeLoad('history',[]),custom=E.safeLoad('custom',[]);
 if(!Array.isArray(favorites))favorites=[];if(!Array.isArray(history))history=[];if(!Array.isArray(custom))custom=[];
 history=history.filter(x=>x&&typeof x.name==='string'&&Array.isArray(x.results));
 custom=custom.filter(x=>x&&typeof x.id==='string'&&typeof x.name==='string'&&Array.isArray(x.positions)&&x.positions.length&&x.positions.every(p=>p&&typeof p.name==='string'));
 let filter={category:'all',search:'',count:'all',favorites:false,limit:18},journalTab='history',session=null,quiz=null,builder=null,toastTimer;
 const allSpreads=()=>[...D.spreads,...custom];
 const getSpread=id=>allSpreads().find(s=>s.id===id);
 const category=id=>D.categories.find(c=>c.id===id)||{name:'自建牌阵',icon:'✧'};
 const getCard=id=>D.cards.find(c=>c.id===Number(id));
 const uuid=()=>Date.now().toString(36)+'-'+E.randomInt(4294967296).toString(36);
 function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
 function persist(key,data){const ok=E.safeSave(key,data);if(!ok)toast('浏览器存储不可用，请导出手记以免丢失。');return ok;}
 function showModal(title,subtitle,body){$('#modal-content').innerHTML=`<div class="modal-header"><div><h2 id="modal-title">${h(title)}</h2>${subtitle?`<p>${h(subtitle)}</p>`:''}</div><button class="icon-button" data-action="close" aria-label="关闭弹窗">×</button></div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();}
 function closeModal(){modal.close();}
 function setNav(view){document.querySelectorAll('[data-nav]').forEach(el=>el.classList.toggle('active',el.dataset.nav===view));}
 function go(hash){if(location.hash===hash)route();else location.hash=hash;}
 function featured(id,tag){const s=getSpread(id);return `<button class="featured" data-action="spread" data-id="${h(id)}"><span class="tag">${tag}</span>${A.layout(s)}<h3>${s.name}</h3><p>${s.description}</p><span class="feature-meta">${s.positions.length} 张牌 <span style="margin:0 7px">·</span> 开始探索 ↗</span></button>`;}
 function spreadCard(s){const cat=category(s.category);return `<article class="spread-card fade-in"><button class="open-hit" data-action="spread" data-id="${h(s.id)}" aria-label="探索${h(s.name)}"></button><div class="category-label">${cat.icon} &nbsp;${cat.name}</div>${A.layout(s)}<h3>${h(s.name)}</h3><p class="description">${h(s.description)}</p><div class="spread-card-bottom"><span>${s.positions.length} 张 · ${Math.max(2,s.positions.length*2)} 分钟</span><span>${h(s.kind||'原创主题')}</span><button class="favorite ${favorites.includes(s.id)?'selected':''}" data-action="favorite" data-id="${h(s.id)}" aria-label="${favorites.includes(s.id)?'取消收藏':'收藏'}${h(s.name)}" aria-pressed="${favorites.includes(s.id)}">${favorites.includes(s.id)?'★':'☆'}</button></div></article>`;}
 function home(){setNav('home');app.innerHTML=`<section class="hero"><div class="hero-copy"><div class="eyebrow">A LITTLE PAUSE. A NEW PERSPECTIVE.</div><h1>在此刻，<br>听见<em>内心的回响。</em></h1><p>让纷杂的思绪暂时安静下来。<br>抽一张牌，与未知相遇，也与自己重新相识。</p><div class="hero-actions"><button class="button primary" data-action="spread" data-id="one">开启今日指引 <span>↗</span></button><a class="button subtle" href="#modes">发现更多玩法 <span>→</span></a></div><div class="hero-footnote"><span>✧</span> ${D.spreads.length} 个主题牌阵 <span>·</span> 78 张完整牌组 <span>·</span> 每一次，都是新的相遇</div></div><div class="hero-art" aria-label="星星、月亮和太阳塔罗插画"><div class="orbit"></div><div class="hero-card">${A.card(D.cards[18])}</div><div class="hero-card">${A.card(D.cards[19])}</div><div class="hero-card">${A.card(D.cards[17])}</div><span class="hero-star">✧</span><span class="art-caption">AS ABOVE, SO WITHIN</span></div></section><section><div class="section-heading"><h2>此刻，想探索什么 <small>START SOMEWHERE</small></h2><span>跟随你的好奇心</span></div><div class="featured-grid">${featured('past','01 / 整理思绪')}${featured('single-0','02 / 靠近关系')}${featured('celtic','03 / 深入探索')}</div></section><section class="library" id="library"><div class="section-heading library-heading"><h2>寻找你的牌阵 <small>THE SPREAD LIBRARY</small></h2><span id="catalog-total">${D.spreads.length} 种探索的可能</span></div><div class="library-controls"><div class="search-box"><span class="search-icon">⌕</span><input id="search" type="search" placeholder="搜索牌阵、主题，或此刻的困惑…" value="${h(filter.search)}" aria-label="搜索牌阵"></div><select id="count-filter" aria-label="按牌数筛选"><option value="all">不限牌数</option><option value="1-3">轻体验 · 1—3 张</option><option value="4-6">多视角 · 4—6 张</option><option value="7-78">深探索 · 7 张以上</option></select><button class="filter-favorites ${filter.favorites?'active':''}" data-action="filter-favorites" aria-pressed="${filter.favorites}">☆ 我的收藏</button></div><div class="library-body"><aside class="category-list" aria-label="牌阵分类">${D.categories.map(c=>`<button class="category-button ${filter.category===c.id?'active':''}" data-action="category" data-id="${c.id}"><span>${c.icon}</span>${c.name}<small>${c.id==='all'?allSpreads().length:allSpreads().filter(s=>s.category===c.id).length}</small></button>`).join('')}</aside><div><div id="catalog" class="catalog-grid"></div><div id="pagination"></div></div></div></section><section class="invitation"><span>✦</span><div><h3>为你的问题，创造一个牌阵</h3><p>自由安排每个位置，让探索拥有自己的形状。</p></div><button class="button" data-action="mode" data-id="builder">创建我的牌阵 ↗</button></section>`;$('#count-filter').value=filter.count;renderCatalog();}
 function renderCatalog(){let list=allSpreads().filter(s=>(filter.category==='all'||s.category===filter.category)&&(!filter.favorites||favorites.includes(s.id)));if(filter.search.trim()){const q=filter.search.trim().toLowerCase();list=list.filter(s=>[s.name,s.description,category(s.category).name,...s.positions.map(p=>p.name)].join(' ').toLowerCase().includes(q));}if(filter.count!=='all'){const[a,b]=filter.count.split('-').map(Number);list=list.filter(s=>s.positions.length>=a&&s.positions.length<=b);}$('#catalog').innerHTML=list.length?list.slice(0,filter.limit).map(spreadCard).join(''):`<div class="empty"><b>留白，也是一个开始</b>${filter.favorites?'还没有收藏符合条件的牌阵，点击星星收藏喜欢的玩法。':'换个关键词，或尝试其他分类。'}</div>`;$('#pagination').innerHTML=`${list.length>filter.limit?'<div class="show-more"><button class="button" data-action="more">再发现 18 个牌阵 ↓</button></div>':''}<div class="result-count">已展示 ${Math.min(filter.limit,list.length)} / ${list.length} 个牌阵</div>`;}
 function modes(){setNav('modes');app.innerHTML=`<section class="page-intro"><div class="eyebrow">A DIFFERENT WAY TO CONNECT</div><h1>让相遇，多一点可能。</h1><p>十种不同的参与方式。一个人静静探索，也可以和朋友一起，分享牌面带来的灵感。</p></section><section class="mode-grid">${D.modes.map(m=>`<button class="mode-card" data-action="mode" data-id="${m.id}"><div class="mode-icon">${m.icon}</div><span class="tag">${m.tag}</span><h3>${m.name}</h3><p>${m.description}</p><span class="arrow">↗</span></button>`).join('')}</section><div class="notice">双人和多人模式使用同一台设备轮流操作，每轮共享一副牌组。</div>`;}
 function journal(){setNav('journal');app.innerHTML=`<section class="page-intro"><div class="eyebrow">YOUR PRIVATE LITTLE UNIVERSE</div><h1>把每一次相遇，轻轻收藏。</h1><p>抽到的牌、当下的想法，以及你创造的牌阵，都保存在当前浏览器里。</p></section><div class="tabs"><button data-action="journal-tab" data-id="history" class="${journalTab==='history'?'active':''}">抽牌手记 <small>${history.length}</small></button><button data-action="journal-tab" data-id="custom" class="${journalTab==='custom'?'active':''}">我的牌阵 <small>${custom.length}</small></button><button data-action="journal-tab" data-id="favorites" class="${journalTab==='favorites'?'active':''}">收藏夹 <small>${favorites.length}</small></button></div><div class="journal-tools"><button class="button small" data-action="import">导入备份</button><button class="button small" data-action="export">导出全部备份 ↓</button><button class="button small" data-action="mode" data-id="builder">＋ 新建牌阵</button></div><div id="journal-content"></div>`;const content=$('#journal-content');if(journalTab==='history')content.innerHTML=`<div class="journal-list">${history.length?history.slice().reverse().map(entry=>`<article class="journal-entry"><h3>${h(entry.name)}</h3><time>${new Date(entry.time).toLocaleString('zh-CN')}</time><span class="subtext">${h(entry.modeLabel||'主题抽牌')} · ${entry.results.length} 张${entry.completed?'':' · 进行中的记录'}</span>${entry.question?`<p>“${h(entry.question)}”</p>`:''}<div class="mini-results">${entry.results.slice(0,8).map(r=>getCard(r.cardId)?A.card(getCard(r.cardId),{mini:true}):'').join('')}</div><div class="entry-actions"><button class="button small" data-action="history-open" data-id="${h(entry.id)}">查看手记 ↗</button><button class="button small danger" data-action="delete-entry" data-id="${h(entry.id)}">删除</button></div></article>`).join(''):'<div class="empty"><b>你的第一篇手记，正在路上</b>抽牌后保存记录，随时回来看看当时的自己。</div>'}</div>`;else if(journalTab==='custom')content.innerHTML=`<div class="custom-list">${custom.length?custom.map(s=>`<article class="journal-entry"><h3>${h(s.name)}</h3><p>${s.positions.length} 个牌位 · 自建牌阵</p><div class="positions-preview">${s.positions.slice(0,5).map(p=>`<span>${h(p.name)}</span>`).join('')}</div><div class="entry-actions"><button class="button small" data-action="spread" data-id="${h(s.id)}">开始抽牌</button><button class="button small danger" data-action="delete-custom" data-id="${h(s.id)}">删除</button></div></article>`).join(''):'<div class="empty"><b>让问题拥有自己的形状</b>用自建牌阵安排每一个探索的位置。</div>'}</div>`;else content.innerHTML=`<div class="catalog-grid" style="margin-bottom:40px">${allSpreads().filter(s=>favorites.includes(s.id)).map(spreadCard).join('')||'<div class="empty"><b>收藏那些让你心动的主题</b>点击牌阵上的星星，即可在这里找到它们。</div>'}</div>`;}
 function setupSpread(id,mode='normal'){const s=getSpread(id);if(!s)return;showModal(s.name,s.description,`<div class="modal-diagram">${A.layout(s)}</div><div class="positions-preview">${s.positions.map((p,i)=>`<span>${i+1} · ${h(p.name)}</span>`).join('')}</div><form id="spread-form" data-spread="${h(id)}" data-mode="${mode}"><label>把此刻想探索的问题写下来 <span class="subtext">（可留空，仅保存在本机）</span><textarea name="question" maxlength="600" placeholder="例如：面对眼前的变化，我可以怎样照顾自己？"></textarea></label><div class="form-row"><label>使用的牌组<select name="deckType"><option value="full">完整 78 张牌</option><option value="major">22 张大阿尔卡那</option></select></label><label>抽牌方式<select name="drawType"><option value="manual">亲手选牌</option><option value="auto">自动随机抽取</option></select></label></div><label class="check-label"><input name="reversals" type="checkbox" checked>包含逆位 · 正逆位独立随机，各 50%</label><p class="subtext">${h(s.kind)} · ${s.positions.length} 张牌 · 约 ${s.positions.length*2} 分钟。牌义是联想提示，你可以写下自己的理解。</p><div class="modal-actions"><button class="button primary" type="submit">洗牌，开始探索 ✦</button><button class="button" type="button" data-action="close">再想一想</button></div></form>`);}
 function begin(spread,config={}){if(session?.results.length)saveRound(true);const source=config.deckType==='major'?D.cards.filter(c=>c.suit==='major'):D.cards;if(spread.positions.length>source.length){toast('这副牌的张数不够，请使用完整牌组。');return;}const deck=config.physical?[]:E.makeDeck(source,config.reversals!==false);session={id:uuid(),spread:structuredClone(spread),mode:config.mode||'normal',question:config.question||'',reversals:config.reversals!==false,deckType:config.deckType||'full',deck,results:[],active:0,deckPage:0,participants:config.participants||[],branchCount:0,created:Date.now(),saving:false,physical:!!config.physical};closeModal();if(location.hash==='#reading')renderReading();else go('#reading');if(config.drawType==='auto'){for(let i=0;i<spread.positions.length;i++){const r=E.takeAt(session.deck,0);session.results.push({...r,revealed:session.mode==='story',note:'',unlocked:false});}renderReading();} }
 function modeLabel(mode){return D.modes.find(m=>m.id===mode)?.name||'主题抽牌';}
 function modeSetup(id){const m=D.modes.find(x=>x.id===id);if(!m)return;if(id==='builder'){openBuilder();return;}if(id==='recommend'){openRecommendation();return;}if(['branch','clarify'].includes(id)){const base=getSpread(id==='branch'?'action':'obstacle');showModal(m.name,m.description,`<div class="positions-preview">${base.positions.map(p=>`<span>${p.name}</span>`).join('')}</div><p>先完成三张基础牌。${id==='branch'?'之后选择一个方向，从剩余牌组继续探索；每条分支会标明来源。':'之后点选一张已翻开的牌，为这个牌位追加说明；补充牌会保留关联。'}</p><form id="mode-form" data-mode="${id}"><label>想探索的问题<textarea name="question" maxlength="600" placeholder="写下你的问题，也可以留空。"></textarea></label><label class="check-label"><input type="checkbox" name="reversals" checked>包含逆位</label><button class="button primary" type="submit">开始探索 ✦</button></form>`);return;}if(id==='quiz'){showModal('牌义挑战','每轮 10 题，选完即可查看解释。',`<form id="quiz-form"><label>挑战内容<select name="kind"><option value="name">看图认牌 · 22 张大阿尔卡那</option><option value="keyword">关键词选择 · 完整 78 张</option><option value="reverse">逆位理解 · 完整 78 张</option></select></label><p class="subtext">认牌题会隐藏牌名与编号；关键词题采用本站的原创牌义。</p><button class="button primary" type="submit">开始挑战 ↗</button></form>`);return;}if(id==='physical'){openPhysical();return;}
 const isGroup=id==='duo'||id==='story';showModal(m.name,m.description,`<form id="mode-form" data-mode="${id}">${isGroup?`<label>参与者昵称 <span class="subtext">（用逗号分隔，${id==='duo'?'恰好 2':'2—8'} 人）</span><input name="participants" value="${id==='duo'?'我，你':'旅人一，旅人二，旅人三'}" maxlength="200" required></label>`:''}<label>${id==='story'?'故事开场（可留空）':'想探索的问题（可留空）'}<textarea name="question" maxlength="600" placeholder="${id==='story'?'在一座月光照亮的小镇上……':'此刻，你想把注意力放在哪里？'}"></textarea></label><label>${id==='duo'?'每人抽取张数':id==='story'?'每人参与轮数':'抽取张数'}<input name="count" type="number" min="1" max="${id==='free'?78:id==='duo'?5:id==='story'?3:12}" value="${id==='blind'?1:id==='story'?1:3}" required></label>${id==='free'?'<label>自定义牌位含义（可留空，一行一个）<textarea name="positions" placeholder="我现在的状态\n我可以尝试的事\n给自己的提醒" maxlength="4000"></textarea></label>':''}<label class="check-label"><input type="checkbox" name="reversals" checked>包含逆位</label><p class="subtext">${id==='duo'?'在同一台设备轮流选牌，可先写感受，选齐后一起翻开。':id==='story'?'每人抽牌、翻开并写一段故事，保存这一段后再交给下一位。':id==='blind'?'翻开牌面后，先写下你的联想，再解锁参考牌义。':'一轮内不重复，最多可抽取完整 78 张。'}</p><button class="button primary" type="submit">洗牌，开始 ✦</button></form>`);}
 function pick(index){if(!session||session.results.length>=session.spread.positions.length)return;if(session.mode==='story'&&session.results.length&&!session.results.at(-1).note.trim()){toast('请先写下并保存这一段故事，再交给下一位。');return;}const result=E.takeAt(session.deck,index);session.results.push({...result,revealed:session.mode==='story',note:'',unlocked:false});session.active=session.results.length-1;session.deckPage=0;renderReading();}
 function allDrawn(){return session&&session.results.length===session.spread.positions.length;}
 function allRevealed(){return allDrawn()&&session.results.every(r=>r.revealed);}
 function layoutStyle(i,n,s){if(s.layout==='custom'){const p=s.positions[i];return `left:${p.x??50}%;top:${p.y??40}%`;}if(s.layout==='celtic'){const p=[[38,48],[39,49],[38,80],[14,48],[38,16],[63,48],[87,84],[87,62],[87,40],[87,18]][i];return p?`left:${p[0]}%;top:${p[1]}%;${i===1?'z-index:2;transform:translate(-50%,-50%) rotate(90deg) scale(.92)':''}`:'';}if(s.layout==='wheel'){const angle=i*Math.PI*2/n;return `left:${50+40*Math.sin(angle)}%;top:${50-36*Math.cos(angle)}%`;}if(s.layout==='horseshoe')return `left:${10+i*80/(n-1)}%;top:${32+35*Math.sin(i*Math.PI/(n-1))}%`;if(s.layout==='star'){const angle=i*Math.PI*2/n;return `left:${50+36*Math.sin(angle)}%;top:${50-33*Math.cos(angle)}%`;}return '';}
 function renderReading(){if(!session){go('#home');return;}setNav('');const s=session.spread,remaining=s.positions.length-session.results.length,current=session.results.length,positioned=['celtic','wheel','horseshoe','star','custom'].includes(s.layout)&&s.positions.length<=16&&!session.branchCount;const pageSize=24,offset=session.deckPage*pageSize;const group=session.participants.length;const turnName=group?session.participants[current%group]:'';app.innerHTML=`<div class="reading-head"><a href="#${session.mode==='normal'?'home':'modes'}">← 返回探索</a><span class="round-status">${session.physical?'实体牌记录':'本轮余牌 '+session.deck.length+' 张 · 不重复'}</span></div><section class="reading-title"><div class="eyebrow">${h(modeLabel(session.mode))} / YOUR MOMENT</div><h1>${h(s.name)}</h1>${session.question?`<p class="question">“${h(session.question)}”</p>`:`<p>${h(s.description)}</p>`}</section><div class="table-status" role="status">${remaining?`${group?'轮到 '+h(turnName)+' · ':''}为「${h(s.positions[current].name)}」选择一张牌 · ${current}/${s.positions.length}`:allRevealed()?'每张牌，都是一个重新认识自己的角度。':'选牌完成。准备好时，翻开你的牌。'}</div>${remaining&&!session.physical?`<div class="deck-strip" id="deck">${session.deck.slice(offset,offset+pageSize).map((r,i)=>`<button class="deck-card" data-action="pick" data-index="${offset+i}" aria-label="选择牌组中第 ${offset+i+1} 张牌">${A.back()}</button>`).join('')}<div class="deck-note">洗牌时已固定牌序与朝向 · 自由选择你想靠近的位置</div>${session.deck.length>pageSize?`<button class="button small" data-action="deck-prev" ${session.deckPage===0?'disabled':''}>← 上一组</button><span class="subtext">${session.deckPage+1} / ${Math.ceil(session.deck.length/pageSize)}</span><button class="button small" data-action="deck-next" ${offset+pageSize>=session.deck.length?'disabled':''}>下一组 →</button>`:''}</div>`:''}<div class="reading-tools">${session.results.length&&!allRevealed()&&session.mode!=='story'?`<button class="button primary small" data-action="reveal-all" ${session.mode==='duo'&&!allDrawn()?'disabled':''}>${session.mode==='duo'?'一起揭晓 ✦':'翻开已选的牌 ✦'}</button>`:''}${session.results.length?'<button class="button small" data-action="save-round">保存本轮手记</button>':''}</div><div class="results-grid ${positioned?'spread-positioned'+(s.layout==='custom'?' custom-positioned':''):''}">${s.positions.map((p,i)=>{const r=session.results[i];return `<div class="result-slot ${!r?'empty-slot':''} ${r?.revealed&&r.reversed?'reversed':''} ${session.active===i&&r?'active':''}" ${positioned?`style="${layoutStyle(i,s.positions.length,s)}"`:''}><div class="position-name"><b>${i+1}</b>${h(p.name)}</div><button class="tarot-card-button" data-action="${r?'select-result':'nothing'}" data-index="${i}" ${r?'':'disabled'} aria-label="${r?.revealed?h(getCard(r.cardId).name)+(r.reversed?'逆位':'正位'):h(p.name)+(r?'，点击翻开':'，等待抽牌')}">${r?.revealed?A.card(getCard(r.cardId)):A.back()}</button>${r?.revealed?`<div class="orientation ${r.reversed?'reverse':''}">${r.reversed?'逆位 ↓':'正位 ↑'}</div>`:r?'<div class="flip-label">等待翻开 ✧</div>':''}${p.parent!=null?`<div class="clarifier-mark">关联第 ${p.parent+1} 张</div>`:''}</div>`;}).join('')}</div><div id="detail-container"></div><div class="reading-bottom">${allRevealed()&&session.deck.length?`<button class="button" data-action="clarify">＋ 为选中牌补充说明</button>${session.mode==='branch'?'<button class="button" data-action="branch">选择新的探索方向 ⑂</button>':''}`:''}${allDrawn()?'<button class="button primary" data-action="save-round">收藏这次相遇 ↓</button>':''}<button class="button" data-action="restart">重新开始</button></div>`;renderDetail();}
 function renderDetail(){if(!session)return;const i=session.active,r=session.results[i],box=$('#detail-container');if(!box)return;if(!r){box.innerHTML='';return;}const p=session.spread.positions[i],c=getCard(r.cardId);if(!r.revealed){box.innerHTML=session.mode==='duo'?`<section class="reading-detail"><h2 class="serif">揭晓之前，先听听自己</h2><p>当前记录：${h(p.name)}。你可以先写下感受，选齐后再一起揭晓。</p><label>我的想法<textarea id="round-note" data-index="${i}" placeholder="此刻的期待、心情，或者想对对方说的话……">${h(r.note)}</textarea></label><button class="button small" data-action="note-save" style="margin-top:12px">保存感受</button></section>`:'';return;}
 const locked=session.mode==='blind'&&!r.unlocked;box.innerHTML=`<section class="reading-detail fade-in"><div class="detail-title"><div><h2>${h(c.name)} <span class="subtext">${r.reversed?'逆位':'正位'}</span></h2><small>${h(p.name)}</small></div><span class="subtext">${i+1} / ${session.results.length}</span></div>${locked?'<p class="prompt">先观察画面：哪一个形状吸引了你？它让你想到了什么？写下自己的联想，再看看参考牌义。</p>':`<p class="keywords">${h(c.keywords)}</p><p>${h(r.reversed?c.reverse:c.upright)}</p><p class="prompt">${h(p.prompt||'围绕这个牌位，你联想到什么具体的经历？')}</p>`}<label>${session.mode==='story'?'这一段故事 · '+h(session.participants[i%session.participants.length]):locked?'我的第一印象':'写给此刻的自己'}<textarea id="round-note" data-index="${i}" maxlength="6000" placeholder="${session.mode==='story'?'让牌面成为故事的一部分，写完后保存，再交给下一位。':'写下感受、现实中的联想，或一个愿意尝试的小行动……'}">${h(r.note)}</textarea></label><div class="modal-actions"><button class="button ${locked?'primary':''} small" data-action="${locked?'unlock':'note-save'}">${locked?'保存联想，展开牌义':'保存'+(session.mode==='story'?'这一段':'想法')}</button>${i>0?'<button class="button small" data-action="detail-prev">← 上一张</button>':''}${i<session.results.length-1?'<button class="button small" data-action="detail-next">下一张 →</button>':''}</div></section>${session.mode==='story'&&session.results.some(x=>x.note)?`<section class="reading-detail"><h2 class="serif">月下的故事</h2>${session.question?`<p>${h(session.question)}</p>`:''}${session.results.map((x,j)=>x.note?`<div class="story-turn"><b>${h(session.participants[j%session.participants.length])} · ${h(getCard(x.cardId).name)}</b><p>${h(x.note)}</p></div>`:'').join('')}</section>`:''}`;}
 function saveRound(silent=false){if(!session?.results.length)return;const entry={id:session.id,name:session.spread.name,question:session.question,time:session.created,mode:session.mode,modeLabel:modeLabel(session.mode),completed:allDrawn(),positions:session.spread.positions,results:session.results.map(r=>({...r})),participants:session.participants,physical:session.physical};const idx=history.findIndex(x=>x.id===entry.id);if(idx>=0)history[idx]=entry;else history.push(entry);const ok=persist('history',history);session.saving=ok;if(!silent&&ok)toast('已保存到「我的手记」，随时回来看看。');}
 function showHistory(id){const entry=history.find(x=>x.id===id);if(!entry)return;showModal(entry.name,new Date(entry.time).toLocaleString('zh-CN')+' · '+entry.modeLabel,`${entry.question?`<p>“${h(entry.question)}”</p>`:''}${entry.results.map((r,i)=>{const c=getCard(r.cardId);if(!c)return '';return `<section class="journal-entry" style="margin-bottom:15px"><div style="display:flex;gap:20px"><div style="width:74px;flex-shrink:0;${r.reversed?'transform:rotate(180deg)':''}">${A.card(c)}</div><div><h3>${h(entry.positions[i]?.name||'补充牌')} · ${c.name}</h3><span class="subtext">${r.reversed?'逆位':'正位'}${entry.positions[i]?.parent!=null?' · 关联第 '+(entry.positions[i].parent+1)+' 张':''}</span><p>${h(r.reversed?c.reverse:c.upright)}</p></div></div><label>当时的想法<textarea class="history-note" data-entry="${h(entry.id)}" data-index="${i}" maxlength="6000">${h(r.note||'')}</textarea></label></section>`;}).join('')}<p class="subtext">修改笔记会自动保存在本机。再次进入玩法会开启新的一轮抽牌。</p>`);}
 function openClarifier(){if(!allRevealed())return;const i=session.active,c=getCard(session.results[i].cardId);showModal('多一个观察的角度','为第 '+(i+1)+' 张「'+c.name+'」追加说明',`<form id="clarifier-form"><label>想进一步理解什么？<input name="focus" maxlength="80" value="关于${h(session.spread.positions[i].name)}的补充" required></label><p class="subtext">从本轮剩余的 ${session.deck.length} 张牌中抽取，保留与原牌的关联。</p><button class="button primary" type="submit">添加补充牌位 ＋</button></form>`);}
 function openBranch(){if(!allRevealed())return;const p=session.spread.positions[session.active];showModal('接下来，想往哪里走？','从「'+p.name+'」继续探索，使用本轮剩余牌组。',`<div class="mode-picker-list">${['寻找可用的支持','看清内在的顾虑','尝试不同的行动','理解尚未看见的需要'].map((n,i)=>`<button class="button" data-action="branch-choice" data-index="${i}">${n} ↗</button>`).join('')}</div>`);}
 function openBuilder(){builder={id:null,name:'',positions:[{name:'现在的我',x:18,y:35},{name:'需要看见的事',x:48,y:20},{name:'可以尝试的行动',x:76,y:55}]};showModal('让牌阵，成为你的形状','拖动牌位安排布局，也可以用输入框精确调整位置。',`<form id="builder-form"><label>牌阵名称<input id="builder-name" name="name" placeholder="给这次探索起个名字" maxlength="50" required></label><div id="builder-canvas" class="builder-canvas" aria-label="牌阵布局编辑区"></div><div id="position-editors"></div><button class="button small" type="button" data-action="builder-add">＋ 添加牌位</button><p class="builder-help">最多 16 个牌位。X、Y 为相对位置百分比；可用键盘输入，不必拖动。</p><div class="modal-actions"><button class="button primary" type="submit">保存我的牌阵 ✦</button><button class="button" type="button" data-action="close">取消</button></div></form>`);renderBuilder();}
 function renderBuilder(){const canvas=$('#builder-canvas');if(!canvas||!builder)return;canvas.innerHTML=builder.positions.map((p,i)=>`<div class="builder-card" data-builder-index="${i}" style="left:calc(${p.x}% - 31px);top:calc(${p.y}% - 35px)"><b>${i+1}</b><span>${h(p.name)}</span></div>`).join('');$('#position-editors').innerHTML=builder.positions.map((p,i)=>`<div class="position-editor"><span class="subtext">${i+1}</span><input aria-label="第${i+1}个牌位名称" data-position-name="${i}" value="${h(p.name)}" maxlength="60" required><input style="width:68px" aria-label="第${i+1}个牌位横向位置" type="number" min="10" max="85" data-position-x="${i}" value="${Math.round(p.x)}"><input style="width:68px" aria-label="第${i+1}个牌位纵向位置" type="number" min="15" max="75" data-position-y="${i}" value="${Math.round(p.y)}"><button class="icon-button" type="button" data-action="builder-remove" data-index="${i}" aria-label="删除第${i+1}个牌位" ${builder.positions.length===1?'disabled':''}>×</button></div>`).join('');}
 function openRecommendation(){showModal('交给一点偶然','先选你关心的方向与能留给自己的时间。',`<form id="recommend-form"><label>想探索的主题<select name="category"><option value="all">什么都可以</option>${D.categories.filter(c=>!['all','classic'].includes(c.id)).map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select></label><label>可用时间<select name="time"><option value="6">6 分钟以内 · 轻体验</option><option value="12">12 分钟以内 · 多视角</option><option value="30">30 分钟以内 · 深探索</option></select></label><label>参与人数<select name="people"><option value="1">一个人</option><option value="2">两个人</option><option value="3">三人及以上</option></select></label><button class="button primary" type="submit">为我随机推荐 ⚄</button></form>`);}
 function openPhysical(){showModal('把真实牌桌的相遇留在这里','实体抽牌结果由你录入，不参与网页随机。',`<form id="physical-setup-form"><label>选择牌阵<select name="spread">${allSpreads().map(s=>`<option value="${h(s.id)}">${h(s.name)} · ${s.positions.length} 张</option>`).join('')}</select></label><label>问题或记录标题<textarea name="question" maxlength="600" placeholder="今天在牌桌上，你探索了什么？"></textarea></label><button class="button primary" type="submit">录入牌面 →</button></form>`);}
 function physicalCards(spread,question){showModal('录入 · '+spread.name,'每张牌只能录入一次，正逆位按你的实体结果选择。',`<form id="physical-cards-form" data-spread="${h(spread.id)}"><input type="hidden" name="question" value="${h(question)}">${spread.positions.map((p,i)=>`<label>${i+1} · ${h(p.name)}<div class="physical-row"><select name="card-${i}"><option value="">选择牌面</option>${D.cards.map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select><select name="orientation-${i}" aria-label="第 ${i+1} 张牌朝向"><option value="upright">正位</option><option value="reverse">逆位</option></select></div></label>`).join('')}<button class="button primary" type="submit">完成录入并保存 ✦</button></form>`);}
 function startQuiz(kind){quiz={kind,deck:E.shuffle(kind==='name'?D.cards.filter(c=>c.suit==='major'):D.cards),index:0,score:0,answered:false};closeModal();newQuizQuestion();go('#quiz');}
 function newQuizQuestion(){const c=quiz.deck[quiz.index];const pool=quiz.kind==='name'?D.cards.filter(x=>x.suit==='major'):D.cards;const others=E.shuffle(pool.filter(x=>x.id!==c.id)).slice(0,3);quiz.options=E.shuffle([c,...others]);quiz.answered=false;quiz.choice=null;}
 function renderQuiz(){setNav('modes');if(!quiz){go('#modes');return;}if(quiz.index>=10){app.innerHTML=`<div class="quiz-area"><section class="page-intro"><div class="eyebrow">A LITTLE MORE FAMILIAR</div><h1>又认识了一点塔罗。</h1><p>完成 10 题，答对 ${quiz.score} 题。</p></section><div style="font-size:75px;color:var(--gold)">✦</div><p>每种理解，都可以从观察和好奇开始。</p><div class="reading-bottom"><button class="button primary" data-action="quiz-again">再来一轮</button><a class="button" href="#modes">返回玩法馆</a></div></div>`;return;}const c=quiz.deck[quiz.index];const imageCard=quiz.kind==='name'?{...c,name:'',en:''}:c;let art=A.card(imageCard);if(quiz.kind==='name')art=art.replace(/<text x="115" y="31"[\s\S]*?<\/text>/,'');const title=quiz.kind==='name'?'这张牌，叫什么名字？':quiz.kind==='reverse'?'哪种理解更贴近这张牌的逆位？':'哪组关键词更贴近这张牌？';app.innerHTML=`<div class="reading-head"><a href="#modes">← 返回玩法馆</a><span class="round-status">${quiz.kind==='name'?'看图认牌':quiz.kind==='reverse'?'逆位理解':'关键词练习'}</span></div><section class="quiz-area"><div class="quiz-score">第 ${quiz.index+1} / 10 题 · 已答对 ${quiz.score} 题</div><h1 class="serif" style="font-size:26px">${title}</h1><div class="quiz-card" style="${quiz.kind==='reverse'?'transform:rotate(180deg)':''}">${art}</div><div class="quiz-options">${quiz.options.map((o,i)=>`<button class="button ${quiz.answered?(o.id===c.id?'correct':quiz.choice===i?'wrong':''):''}" data-action="quiz-answer" data-index="${i}" ${quiz.answered?'disabled':''}>${h(quiz.kind==='name'?o.name:quiz.kind==='reverse'?o.reverse.split('。')[0]:o.keywords)}</button>`).join('')}</div>${quiz.answered?`<div class="quiz-feedback">${quiz.options[quiz.choice].id===c.id?'✦ 答对了':'这次的参考答案是：'+h(c.name)}<br>${h(quiz.kind==='reverse'?c.reverse:c.upright)}</div><button class="button primary" data-action="quiz-next">${quiz.index===9?'查看本轮成绩':'下一张 →'}</button>`:''}</section>`;}
 function help(){showModal('关于这场月下的相遇','抽牌规则与使用说明',`<ul class="about-list"><li><b>随机来源：</b>使用浏览器 Web Crypto 安全随机数，经拒绝采样和 Fisher–Yates 洗牌生成无偏牌序。它属于密码学安全随机，不宣称物理真随机。</li><li><b>完整牌组：</b>78 张牌，包括 22 张大阿尔卡那与四花色各 14 张小阿尔卡那。牌面为本站原创象征插画。</li><li><b>公平抽取：</b>洗牌时固定牌序和每张牌的正逆位。开启逆位时各 50%，同轮不会出现重复牌；补充和分支沿用剩余牌组。问题内容不影响抽牌。</li><li><b>主题说明：</b>${D.spreads.length} 个入口包含常见牌阵与本站原创主题变体，部分主题共享布局。牌义与提问是预先整理的内容。</li><li><b>隐私与保存：</b>问题、手记、收藏与自建牌阵保存在当前浏览器的本机存储中。清理浏览器数据或更换设备后不会自动同步，可在我的手记导出备份。</li><li><b>共同体验：</b>双人和多人使用同一设备轮流抽牌。盲解先写联想，再展开参考；实体录入记录你的真实抽牌。</li></ul><div class="sources"><a href="https://labyrinthos.co/pages/tarot-spreads-list" target="_blank" rel="noopener">牌阵主题参考 ↗</a><a href="https://biddytarot.com/masterclass/celtic-cross/" target="_blank" rel="noopener">凯尔特十字参考 ↗</a><a href="https://www.w3.org/TR/webcrypto/#Crypto-method-getRandomValues" target="_blank" rel="noopener">随机接口规范 ↗</a></div><div class="modal-actions"><button class="button primary" data-action="close">继续探索</button></div>`);}
 function download(name,body,type='application/json'){const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
 function importBackup(){showModal('导入月下备份','备份会与现有数据合并；相同记录保留本机版本。',`<label>选择本站导出的 JSON 备份文件<input type="file" id="backup-file" accept=".json,application/json"></label><p class="subtext">备份包含个人笔记，请只导入你信任的文件。</p>`);}
 function validateBackup(data){if(!data||data.format!=='moonlit-tarot-v1'||!Array.isArray(data.history)||!Array.isArray(data.custom)||!Array.isArray(data.favorites))throw Error('这不是月下塔罗的有效备份。');for(const s of data.custom){if(typeof s.id!=='string'||!s.id.startsWith('custom-')||s.id.length>100||typeof s.name!=='string'||s.name.length>100||!Array.isArray(s.positions)||s.positions.length<1||s.positions.length>16||!s.positions.every(p=>typeof p.name==='string'&&p.name.length<=100&&(p.x===undefined||Number.isFinite(p.x))&&(p.y===undefined||Number.isFinite(p.y))))throw Error('自建牌阵数据不完整。');}for(const entry of data.history){if(typeof entry.id!=='string'||typeof entry.name!=='string'||!Number.isFinite(entry.time)||!Array.isArray(entry.positions)||!entry.positions.every(p=>p&&typeof p.name==='string')||!Array.isArray(entry.results)||entry.results.length>78||entry.results.some(r=>!getCard(r.cardId)||typeof r.reversed!=='boolean'||(r.note!=null&&typeof r.note!=='string'))||new Set(entry.results.map(r=>r.cardId)).size!==entry.results.length)throw Error('抽牌记录数据不完整。');}if(!data.favorites.every(x=>typeof x==='string'))throw Error('收藏数据不完整。');return data;}
 function route(){const view=location.hash.slice(1).split('?')[0]||'home';if(modal.open)closeModal();if(view==='reading')renderReading();else if(view==='quiz')renderQuiz();else if(view==='modes')modes();else if(view==='journal')journal();else home();window.scrollTo(0,0);}
 document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,id=el.dataset.id,index=Number(el.dataset.index);try{
 if(a==='close')closeModal();else if(a==='help')help();else if(a==='spread')setupSpread(id);else if(a==='mode')modeSetup(id);else if(a==='favorite'){favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];persist('favorites',favorites);if(location.hash==='#journal')journal();else renderCatalog();}else if(a==='filter-favorites'){filter.favorites=!filter.favorites;filter.limit=18;el.classList.toggle('active',filter.favorites);el.setAttribute('aria-pressed',filter.favorites);renderCatalog();}else if(a==='category'){filter.category=id;filter.limit=18;document.querySelectorAll('.category-button').forEach(b=>b.classList.toggle('active',b.dataset.id===id));renderCatalog();}else if(a==='more'){filter.limit+=18;renderCatalog();}else if(a==='journal-tab'){journalTab=id;journal();}else if(a==='history-open')showHistory(id);else if(a==='delete-entry'){showModal('删除这篇手记？','仅移除这条本机记录，其他手记不受影响。',`<button class="button danger" data-action="confirm-delete-entry" data-id="${h(id)}">删除这条记录</button> <button class="button" data-action="close">保留</button>`);}else if(a==='confirm-delete-entry'){history=history.filter(x=>x.id!==id);persist('history',history);closeModal();journal();}else if(a==='delete-custom'){showModal('删除这个自建牌阵？','已保存的抽牌记录仍然保留。',`<button class="button danger" data-action="confirm-delete-custom" data-id="${h(id)}">删除牌阵</button> <button class="button" data-action="close">保留</button>`);}else if(a==='confirm-delete-custom'){custom=custom.filter(x=>x.id!==id);favorites=favorites.filter(x=>x!==id);persist('custom',custom);persist('favorites',favorites);closeModal();journal();}else if(a==='export')download('月下塔罗备份-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({format:'moonlit-tarot-v1',exportedAt:new Date().toISOString(),history,custom,favorites},null,2));else if(a==='import')importBackup();
 else if(a==='pick')pick(index);else if(a==='deck-prev'){session.deckPage--;renderReading();}else if(a==='deck-next'){session.deckPage++;renderReading();}else if(a==='select-result'){const r=session.results[index];if(!r)return;session.active=index;if(!r.revealed){if(session.mode==='duo'&&!allDrawn()){renderReading();return;}r.revealed=true;}renderReading();}else if(a==='reveal-all'){if(session.mode==='duo'&&!allDrawn())return;session.results.forEach(r=>r.revealed=true);renderReading();}else if(a==='save-round')saveRound();else if(a==='note-save'){saveRound(true);toast(session.mode==='story'?'故事已保存，可以交给下一位了。':'想法已保存。');if(session.mode==='story')renderDetail();}else if(a==='unlock'){const r=session.results[session.active];if(!r.note.trim()){toast('先写下一点自己的联想，再展开参考牌义。');return;}r.unlocked=true;saveRound(true);renderDetail();}else if(a==='detail-prev'||a==='detail-next'){session.active+=a==='detail-prev'?-1:1;renderReading();}else if(a==='clarify')openClarifier();else if(a==='branch')openBranch();else if(a==='branch-choice'){const t=['寻找可用的支持','看清内在的顾虑','尝试不同的行动','理解尚未看见的需要'][index];session.spread.positions.push({name:t,prompt:'从原牌出发，关于“'+t+'”，这张新牌带来什么角度？',parent:session.active});session.branchCount++;closeModal();renderReading();}else if(a==='restart'){showModal('开启新的一轮？','当前手记会先保存，新一轮使用完整的所选牌组重新洗牌。',`<button class="button primary" data-action="confirm-restart">保存并重新开始</button> <button class="button" data-action="close">继续本轮</button>`);}else if(a==='confirm-restart'){const old=session;saveRound(true);if(old.physical){physicalCards(old.spread,old.question);return;}const base=structuredClone(old.spread);base.positions=base.positions.filter(p=>p.parent==null);begin(base,{mode:old.mode,question:old.question,reversals:old.reversals,deckType:old.deckType,participants:old.participants});}
 else if(a==='builder-add'){if(builder.positions.length>=16){toast('一个自建牌阵最多 16 个牌位。');return;}builder.positions.push({name:'新的探索位置',x:25+(builder.positions.length%3)*23,y:20+Math.floor(builder.positions.length/3)%3*22});renderBuilder();}else if(a==='builder-remove'){if(builder.positions.length>1)builder.positions.splice(index,1);renderBuilder();}else if(a==='quiz-answer'){if(quiz.answered)return;quiz.answered=true;quiz.choice=index;if(quiz.options[index].id===quiz.deck[quiz.index].id)quiz.score++;renderQuiz();}else if(a==='quiz-next'){quiz.index++;if(quiz.index<10)newQuizQuestion();renderQuiz();}else if(a==='quiz-again')startQuiz(quiz.kind);else if(a==='recommend-spread')setupSpread(id);else if(a==='recommend-mode')modeSetup(id);
 }catch(error){toast(error.message||'刚才的操作没有完成，请再试一次。');console.error(error);}});
 document.addEventListener('input',e=>{const el=e.target;if(el.id==='search'){filter.search=el.value;filter.limit=18;renderCatalog();}else if(el.id==='round-note'&&session){const r=session.results[Number(el.dataset.index)];if(r)r.note=el.value;}else if(el.classList.contains('history-note')){const entry=history.find(x=>x.id===el.dataset.entry);if(entry?.results[Number(el.dataset.index)]){entry.results[Number(el.dataset.index)].note=el.value;persist('history',history);}}else if(el.dataset.positionName!==undefined){const i=Number(el.dataset.positionName);builder.positions[i].name=el.value;const span=$(`[data-builder-index="${i}"] span`);if(span)span.textContent=el.value;}else if(el.dataset.positionX!==undefined||el.dataset.positionY!==undefined){const axis=el.dataset.positionX!==undefined?'x':'y',i=Number(el.dataset.positionX??el.dataset.positionY);builder.positions[i][axis]=Math.max(axis==='x'?10:15,Math.min(axis==='x'?85:75,Number(el.value)||15));const c=$(`[data-builder-index="${i}"]`);if(c)c.style[axis==='x'?'left':'top']=`calc(${builder.positions[i][axis]}% - ${axis==='x'?31:35}px)`;}});
 document.addEventListener('change',async e=>{if(e.target.id==='count-filter'){filter.count=e.target.value;filter.limit=18;renderCatalog();}if(e.target.id==='backup-file'){try{const file=e.target.files[0];if(!file)return;if(file.size>10000000)throw Error('备份超过 10 MB，请选择较小的文件。');const data=validateBackup(JSON.parse(await file.text()));const before={history:history.length,custom:custom.length};for(const entry of data.history)if(!history.some(x=>x.id===entry.id))history.push(entry);for(const s of data.custom)if(!custom.some(x=>x.id===s.id))custom.push(s);favorites=[...new Set([...favorites,...data.favorites])];history.sort((a,b)=>a.time-b.time);const ok1=persist('history',history),ok2=persist('custom',custom),ok3=persist('favorites',favorites);closeModal();journal();if(ok1&&ok2&&ok3)toast(`已导入 ${history.length-before.history} 篇手记、${custom.length-before.custom} 个牌阵。`);}catch(error){toast(error.message||'无法读取这份备份。');}}});
 document.addEventListener('submit',e=>{const form=e.target;if(!form.id)return;e.preventDefault();const data=new FormData(form);try{
 if(form.id==='spread-form')begin(getSpread(form.dataset.spread),{question:data.get('question').trim(),deckType:data.get('deckType'),drawType:data.get('drawType'),reversals:data.has('reversals'),mode:form.dataset.mode});
 else if(form.id==='mode-form'){const mode=form.dataset.mode,n=Number(data.get('count')||3);let positions=[],participants=[];if(mode==='branch'||mode==='clarify'){begin(getSpread(mode==='branch'?'action':'obstacle'),{mode,question:data.get('question').trim(),reversals:data.has('reversals')});return;}if(!Number.isInteger(n)||n<1||n>(mode==='free'?78:mode==='duo'?5:mode==='story'?3:12))throw Error('请填写范围内的整数张数。');if(mode==='duo'||mode==='story'){participants=data.get('participants').split(/[,，\n]/).map(x=>x.trim()).filter(Boolean);if(mode==='duo'&&participants.length!==2)throw Error('双人模式请填写两个昵称。');if(mode==='story'&&(participants.length<2||participants.length>8))throw Error('故事接龙需要 2—8 位参与者。');positions=Array.from({length:n*participants.length},(_,i)=>({name:participants[i%participants.length]+' · 第 '+(Math.floor(i/participants.length)+1)+' 轮',prompt:mode==='story'?'让这张牌成为故事接下来的转折。':'观察自己的感受，也为对方的理解留一点空间。'}));}else{const names=String(data.get('positions')||'').split('\n').map(x=>x.trim()).filter(Boolean);if(names.length&&names.length!==n)throw Error('自定义牌位行数需要与抽取张数一致。');positions=Array.from({length:n},(_,i)=>({name:names[i]||'自由探索 '+(i+1),prompt:'对于这个位置，你有什么自己的理解？'}));}begin({id:'mode-'+mode,name:modeLabel(mode),positions,description:D.modes.find(m=>m.id===mode).description,layout:'line',kind:'互动玩法'},{mode,participants,question:data.get('question').trim(),reversals:data.has('reversals')});}
 else if(form.id==='clarifier-form'){session.spread.positions.push({name:data.get('focus').trim(),prompt:'这是一张补充牌，请与关联的原牌结合观察。',parent:session.active});session.branchCount++;closeModal();renderReading();}
 else if(form.id==='builder-form'){const name=data.get('name').trim();if(!name||builder.positions.some(p=>!p.name.trim()))throw Error('请填写牌阵名称和每个牌位的含义。');const s={id:'custom-'+uuid(),name,category:'custom',positions:builder.positions.map(p=>({name:p.name.trim(),x:p.x,y:p.y,prompt:'关于“'+p.name.trim()+'”，你从牌面联想到什么？'})),description:'由你安排位置与含义的专属探索。',layout:'custom',kind:'自建牌阵'};custom.push(s);persist('custom',custom);closeModal();journalTab='custom';go('#journal');toast('专属牌阵已保存，可以开始抽牌了。');}
 else if(form.id==='recommend-form'){const people=Number(data.get('people')),cat=data.get('category'),time=Number(data.get('time'));if(people>1){const id=people===2?['duo','story'][E.randomInt(2)]:'story';showModal('这一刻，试试这个玩法',people+' 人及以上 · 同一设备轮流体验',`<div class="notice">${D.modes.find(m=>m.id===id).name}</div><p>${D.modes.find(m=>m.id===id).description}</p><p class="subtext">多人体验时长取决于分享节奏，可在下一步减少每人轮数。你选择的主题：${category(cat).name}，可以作为共同问题。</p><button class="button primary" data-action="recommend-mode" data-id="${id}">进入玩法 →</button>`);}else{const pool=allSpreads().filter(s=>(cat==='all'||s.category===cat)&&s.positions.length*2<=time);if(!pool.length){toast('这个主题需要更多时间，请放宽时间筛选。');return;}const s=pool[E.randomInt(pool.length)];showModal('偶然，把你带到这里',category(s.category).name+' · '+s.positions.length+' 张牌',`<div class="modal-diagram">${A.layout(s)}</div><h3 class="serif" style="text-align:center;font-size:25px">${h(s.name)}</h3><p style="text-align:center;margin-top:15px">${h(s.description)}</p><div class="modal-actions"><button class="button primary" data-action="recommend-spread" data-id="${h(s.id)}">就探索这个 →</button><button class="button" data-action="mode" data-id="recommend">重新选择条件</button></div>`);}}
 else if(form.id==='quiz-form')startQuiz(data.get('kind'));
 else if(form.id==='physical-setup-form')physicalCards(getSpread(data.get('spread')),data.get('question').trim());
 else if(form.id==='physical-cards-form'){const spread=getSpread(form.dataset.spread),results=spread.positions.map((p,i)=>{const v=data.get('card-'+i);if(v==='')throw Error('请为每个位置选择一张牌。');return {cardId:Number(v),reversed:data.get('orientation-'+i)==='reverse',revealed:true,note:'',unlocked:true};});if(new Set(results.map(r=>r.cardId)).size!==results.length)throw Error('同一副实体牌中不能重复录入一张牌。');begin(spread,{mode:'physical',question:data.get('question'),physical:true});session.results=results;renderReading();saveRound(true);toast('实体抽牌已录入并保存。');}
 }catch(error){toast(error.message||'操作未完成，请检查填写内容。');console.error(error);}});
 let dragging=null;
 document.addEventListener('pointerdown',e=>{const card=e.target.closest('[data-builder-index]');if(!card||!builder)return;const bounds=$('#builder-canvas').getBoundingClientRect();dragging={index:Number(card.dataset.builderIndex),bounds,card};card.setPointerCapture(e.pointerId);});
 document.addEventListener('pointermove',e=>{if(!dragging)return;const {index,bounds,card}=dragging,p=builder.positions[index];p.x=Math.round(Math.max(10,Math.min(85,(e.clientX-bounds.left)/bounds.width*100)));p.y=Math.round(Math.max(15,Math.min(75,(e.clientY-bounds.top)/bounds.height*100)));card.style.left=`calc(${p.x}% - 31px)`;card.style.top=`calc(${p.y}% - 35px)`;$(`[data-position-x="${index}"]`).value=p.x;$(`[data-position-y="${index}"]`).value=p.y;});
 document.addEventListener('pointerup',()=>{dragging=null;});document.addEventListener('pointercancel',()=>{dragging=null;});
 modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
 window.addEventListener('hashchange',route);window.addEventListener('beforeunload',()=>{if(session?.results.length)saveRound(true);});
 route();
})();
